export type LogoName = keyof typeof logos;

export function TechLogo({ name, className }: { name: LogoName; className?: string }) {
  const logo = logos[name];
  return (
    <svg
      viewBox={logo.viewBox}
      aria-hidden="true"
      focusable="false"
      className={className}
      dangerouslySetInnerHTML={{ __html: logo.body }}
    />
  );
}
